const fail=message=>Object.assign(Error(message),{status:400});
const extensions=['pdf','txt','csv','png','jpg','jpeg','webp','docx','xlsx','pptx','mp3','wav','mp4','webm'];
export function quizFiles(files=[],{maxFiles=3,allowed=extensions}={}){if(!Array.isArray(files)||files.length>maxFiles)throw fail('Too many uploaded files.');return files.map(f=>{const name=String(f.name||'').replace(/[\\/<>:\x00-\x1f]/g,'_').slice(0,120),ext=name.split('.').pop().toLowerCase(),data=f.data;if(!allowed.includes(ext)||typeof data!=='string'||!/^[A-Za-z0-9+/]*={0,2}$/.test(data)||data.length%4)throw fail('This file type or file encoding is not allowed.');const size=data.length*3/4-(data.endsWith('==')?2:data.endsWith('=')?1:0);if(!size||size>1048576)throw fail('Each uploaded file must be 1 MB or smaller.');return{name,data,size};});}
export function questionImage(image){if(!image)return null;const f=quizFiles([image],{maxFiles:1,allowed:['png','jpg','jpeg','webp']})[0],bytes=atob(f.data.slice(0,48)),png=bytes.startsWith('\x89PNG\r\n\x1a\n'),jpg=bytes.startsWith('\xff\xd8\xff'),webp=bytes.startsWith('RIFF')&&bytes.slice(8,12)==='WEBP';if(!png&&!jpg&&!webp)throw fail('Choose a real PNG, JPEG or WebP image. SVG and HTML are not accepted.');return{...f,mime:png?'image/png':jpg?'image/jpeg':'image/webp',alt:String(image.alt||'Question image').slice(0,300)};}
export const QUIZ_FILE_EXTENSIONS=extensions;
